update integration_schema.sync_alert a set status='RESOLVED' where a.job_code=#{jobCode}
  and (a.category='SYNC_FAILURE' or a.category like 'SOURCE_%' or a.category like 'CHECKPOINT_%' or a.category='INVALID_PAGE'
    or (a.category='STALE' and not exists(
    select 1 from integration_schema.sync_checkpoint c where c.job_code=a.job_code and 
  )))
